```java
import java.io.*;
import javax.servlet.http.*;
import com.fasterxml.jackson.databind.ObjectMapper;

// This class demonstrates a secure way of handling data using JSON
public class SecureJsonHandler extends HttpServlet {
    // Use a library like Jackson to handle data as plain text, not as executable objects
    private final ObjectMapper mapper = new ObjectMapper();

    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws IOException {
        try {
            // Instead of deserializing binary Java objects, we parse a JSON string.
            // This prevents the instantiation of arbitrary classes through "gadget chains."
            String jsonInput = request.getReader().lines().reduce("", String::concat);

            // We explicitly map the input to a specific, trusted POJO (Plain Old Java Object)
            // If the JSON contains extra fields or malicious types, the mapper handles it safely.
            UserDTO user = mapper.readValue(jsonInput, UserDTO.class);

            response.getWriter().println("User received: " + user.getName());
        } catch (Exception e) {
            response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
            response.getWriter().println("Invalid input format.");
        }
    }
}

// A simple, safe data transfer object
class UserDTO {
    private String name;
    public String getName() { return name; }
    public void setName(String name) { this.name = name; }
}
```

